18	import java.util.Collection;
19	
20	import org.springframework.samples.petclinic.model.Owner;
21	
22	/**
23	 * Counts existing owners that are namesakes of a given owner: identical first name and
24	 * last name compared case-insensitively.
25	 */
26	public final class NamesakeCounter {
27	
28	    private NamesakeCounter() {
29	    }
30	
31	    public static int count(Collection<Owner> existing, Owner owner) {
32	        String firstName = owner.getFirstName();
33	        String lastName = owner.getLastName();
34	        return (int) existing.stream()
35	            .filter(o -> firstName.equalsIgnoreCase(o.getFirstName())
36	                && lastName.equalsIgnoreCase(o.getLastName()))
37	            .count();
38	    }
39	}
