16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java((owner.getFirstName().charAt(0) + \".\" + owner.getLastName().charAt(0) + \".\").toUpperCase())")
24	    @Mapping(target = "householdId", expression = "java(org.springframework.samples.petclinic.service.HouseholdMatcher.householdId(owner))")
25	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.service.IdentityKey.of(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.service.CheckDigit.of(owner.getCustomerCode()))")
27	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
28	    @Mapping(target = "membershipLevel", expression = "java(Math.min(3, 1 + (owner.getEmail() != null && !owner.getEmail().isBlank() ? 1 : 0) + (Integer.valueOf(0).equals(owner.getNamesakeCount()) ? 1 : 0)))")
29	    @Mapping(target = "locality", expression = "java(owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')))")
30	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
31	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.service.AgeBand.of(owner))")
32	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.service.TelephoneFormatter.display(owner.getTelephone()))")
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    Owner toOwner(OwnerDto ownerDto);
36	
37	    @Mapping(target = "id", ignore = true)
38	    @Mapping(target = "pets", ignore = true)
39	    @Mapping(target = "telephone", qualifiedByName = "normalizeTelephone")
40	    @Mapping(target = "address", expression = "java(org.springframework.samples.petclinic.service.AddressNormalizer.normalize(ownerDto.getAddress()))")
41	    @Mapping(target = "postcode", expression = "java(org.springframework.samples.petclinic.service.PostcodeValidator.validate(ownerDto.getCity(), ownerDto.getPostcode()))")
42	    @Mapping(target = "registrationDate", expression = "java(org.springframework.samples.petclinic.service.RegistrationDateValidator.validate(ownerDto.getRegistrationDate()))")
43	    @Mapping(target = "email", expression = "java(org.springframework.samples.petclinic.service.DisposableEmailDomain.validate(ownerDto.getEmail()))")
44	    Owner toOwner(OwnerFieldsDto ownerDto);
45	
46	    /**
47	     * Normalise a telephone to E.164 for storage: keep an explicit leading '+' and country
48	     * code when present, otherwise assume '+61' and drop a single leading national '0'.
49	     * Spaces, dashes and brackets are stripped; the result must have 8 to 15 digits after
50	     * the '+', else the number is rejected as invalid.
51	     */
52	    @Named("normalizeTelephone")
53	    default String normalizeTelephone(String telephone) {
54	        if (telephone == null) {
55	            return null;
56	        }
57	        boolean international = telephone.trim().startsWith("+");
58	        String digits = telephone.replaceAll("\\D", "");
59	        if (!international) {
60	            if (digits.startsWith("0")) {
61	                digits = digits.substring(1);
62	            }
63	            digits = "61" + digits;
64	        }
65	        if (digits.length() < 8 || digits.length() > 15) {
66	            throw new IllegalArgumentException("Telephone cannot form a valid E.164 number: " + telephone);
67	        }
68	        org.springframework.samples.petclinic.service.E164NationalLength.check(digits);
69	        return "+" + digits;
70	    }
71	
72	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
73	
74	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
75	
76	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
77	        OwnerPageDto ownerPageDto = new OwnerPageDto();
78	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
79	        ownerPageDto.setPage(ownerPage.getNumber());
80	        ownerPageDto.setSize(ownerPage.getSize());
81	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
82	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
83	        return ownerPageDto;
84	    }
85	}
